#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    cin >> s;
    long long diff = 0;
    for (char c : s) {
        if (c >= 'A' && c <= 'Z') diff++;
        else if (c >= 'a' && c <= 'z') diff--;
    }
