import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] data = System.in.readAllBytes();
        long diff = 0;
        for (byte c : data) {
            if (c >= 'A' && c <= 'Z') diff++;
            else if (c >= 'a' && c <= 'z') diff--;
        }
        System.out.println(diff);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	diff := 0
	for _, c := range data {
		if c >= 'A' && c <= 'Z' {
			diff++
		} else if c >= 'a' && c <= 'z' {
			diff--
		}
	}
	fmt.Println(diff)
}
